# LFS 13.1-systemd, chapter08: Binutils-2.47.
# Generated by tools/lfs-extract.py from the LFS book; do not edit by hand.
enter_src binutils
# The book refers to sources and patches as ../<file>.
ln -sf "$SOURCES"/* ..

mkdir -v build
cd       build

../configure --prefix=/usr       \
             --sysconfdir=/etc   \
             --enable-ld=default \
             --enable-plugins    \
             --enable-shared     \
             --disable-werror    \
             --enable-64-bit-bfd \
             --enable-new-dtags  \
             --with-system-zlib  \
             --with-lib-path=/usr/lib \
             --enable-default-hash-style=gnu

make tooldir=/usr

make tooldir=/usr install

rm -rfv /usr/lib/lib{bfd,ctf,ctf-nobfd,gprofng,opcodes,sframe}.a \
        /usr/share/doc/gprofng/
